import pty, os, select, sys, pathlib, time

def run_with_input(cmd, cwd, inputs, timeout=5):
    pid, fd = pty.fork()
    if pid == 0:
        if cwd:
            os.chdir(cwd)
        os.execvp(cmd[0], cmd)
    else:
        output = b""
        input_idx = 0
        last_activity = time.time()
        while True:
            r, w, _ = select.select([fd], [fd] if input_idx < len(inputs) else [], [], 0.1)
            if r:
                try:
                    data = os.read(fd, 4096)
                    if not data:
                        break
                    output += data
                    sys.stdout.buffer.write(data)
                    sys.stdout.buffer.flush()
                    last_activity = time.time()
                except OSError:
                    break
            if w and input_idx < len(inputs):
                time.sleep(0.3)
                os.write(fd, inputs[input_idx].encode())
                input_idx += 1
                last_activity = time.time()
            if time.time() - last_activity > timeout:
                if input_idx < len(inputs):
                    time.sleep(0.2)
                    os.write(fd, inputs[input_idx].encode())
                    input_idx+=1
                    last_activity=time.time()
                    continue
                break
            try:
                pid_done, status = os.waitpid(pid, os.WNOHANG)
                if pid_done != 0:
                    try:
                        while True:
                            r2, _, _ = select.select([fd], [], [], 0.1)
                            if not r2:
                                break
                            data = os.read(fd, 4096)
                            if not data:
                                break
                            output+=data
                            sys.stdout.buffer.write(data)
                            sys.stdout.buffer.flush()
                    except OSError:
                        pass
                    break
            except ChildProcessError:
                break
        return output

def test(name, inputs):
    import shutil, pathlib
    shutil.rmtree("/tmp/gramtest", ignore_errors=True)
    pathlib.Path("/tmp/gramtest").mkdir(parents=True)
    print(f"\n=== testing inputs {inputs} ===")
    run_with_input(["/workspace/executable", "init"], "/tmp/gramtest", inputs)
    print("\n--- dir ---")
    for p in pathlib.Path("/tmp/gramtest").rglob("*"):
        print(p)
        if p.is_file():
            try:
                print(p.read_text()[:5000])
            except:
                pass
    print("=== end ===\n")

