        }).collect()
    }

    fn to_kebab(name: &str) -> String {
        name.replace('_', "-")
    }

    fn to_upper_snake(name: &str) -> String {
        name.to_uppercase()
    }

    fn print_question(label: &str, default: Option<&str>) {
        eprint!("\x1b[33m?\x1b[39m \x1b[1m{}\x1b[0m ", label);
        if let Some(d) = default {
            eprint!("\x1b[38;5;8m({})\x1b[39m ", d);
        }
        eprint!("\x1b[38;5;8m›\x1b[39m ");
        let _ = io::stderr().flush();
    }

    fn print_success(label: &str, value: &str) {
        eprint!("\x1b[32m✔\x1b[39m \x1b[1m{}\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32m{}\x1b[39m\n", label, value);
        let _ = io::stderr().flush();
    }

    fn print_error(msg: &str) {
        eprint!("\x1b[31m✘\x1b[39m \x1b[31m{}\x1b[39m\n", msg);
        let _ = io::stderr().flush();
    }

    fn read_line() -> String {
        let mut s = String::new();
        io::stdin().read_line(&mut s).unwrap();
        s.trim_end_matches(&['\r','\n'][..]).to_string()
    }

    pub fn run_init(grammar_path: &str) {
        let base = PathBuf::from(grammar_path);
        std::fs::create_dir_all(&base).unwrap_or_else(|e| { eprintln!("\x1b[31mError:\x1b[0m {}", e); std::process::exit(1); });

        // Parser name
        let parser_name = loop {
            print_question("Parser name", None);
            let input = read_line();
            if input.is_empty() {
                continue;
            }
            if !input.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_') {
                print_error("The name must be lowercase and contain only letters, digits, and underscores");
                continue;
            }
            print_success("Parser name", &input);
            break input;
        };

        let camel_default = to_camelcase(&parser_name);
        let camelcase = loop {
            print_question("CamelCase name", Some(&camel_default));
            let input = read_line();
            let val = if input.is_empty() { camel_default.clone() } else { input.clone() };
            print_success("CamelCase name", &val);
            break val;
        };

        let title_default = camelcase.clone();
        let title = loop {
            print_question("Title (human-readable name)", Some(&title_default));
            let input = read_line();
            let val = if input.is_empty() { title_default.clone() } else { input.clone() };
            print_success("Title (human-readable name)", &val);
            break val;
        };

        let description = loop {
            print_question("Description", None);
            let input = read_line();
            print_success("Description", &input);
            break input;
        };

        let repo_default = format!("https://github.com/tree-sitter/tree-sitter-{}", parser_name);
        let repository = loop {
            print_question("Repository URL", None);
            let input = read_line();
            let val = if input.is_empty() { repo_default.clone() } else { input.clone() };
            print_success("Repository URL", &val);
            break val;
        };

        let funding = loop {
            print_question("Funding URL", None);
            let input = read_line();
            print_success("Funding URL", &input);
            break input;
        };

        let scope_default = format!("source.{}", parser_name);
        let scope = loop {
            print_question("TextMate scope", Some(&scope_default));
            let input = read_line();
            let val = if input.is_empty() { scope_default.clone() } else { input.clone() };
            if !(val.starts_with("source.") || val.starts_with("text.")) {
                print_error("The scope must start with 'source.' or 'text.'");
                continue;
            }
            print_success("TextMate scope", &val);
            break val;
        };

        let filetypes_default = parser_name.clone();
        let file_types_input = loop {
            print_question("File types (space-separated)", Some(&filetypes_default));
            let input = read_line();
            let val = if input.is_empty() { filetypes_default.clone() } else { input.clone() };
            print_success("File types (space-separated)", &val);
            break val;
        };
        let file_types: Vec<String> = file_types_input.split_whitespace().map(|s| s.to_string()).collect();

        let version_default = "0.1.0";
        let version = loop {
            print_question("Version", Some(version_default));
            let input = read_line();
            let val = if input.is_empty() { version_default.to_string() } else { input.clone() };
            match semver::Version::parse(&val) {
                Ok(_) => {
                    print_success("Version", &val);
                    break val;
                }
                Err(e) => {
                    print_error(&e.to_string());
                    continue;
                }
            }
        };

        let license_default = "MIT";
        let license = loop {
            print_question("License", Some(license_default));
            let input = read_line();
            let val = if input.is_empty() { license_default.to_string() } else { input.clone() };
            print_success("License", &val);
            break val;
        };

        let author_name = loop {
            print_question("Author name", None);
            let input = read_line();
            print_success("Author name", &input);
            break input;
        };

        let author_email = loop {
            print_question("Author email", None);
            let input = read_line();
            print_success("Author email", &input);
            break input;
        };

        let author_url = loop {
            print_question("Author URL", None);
            let input = read_line();
            print_success("Author URL", &input);
            break input;
        };

        let namespace_default = "io.github.tree-sitter";
        let namespace = loop {
            print_question("Package namespace", Some(namespace_default));
            let input = read_line();
            let val = if input.is_empty() { namespace_default.to_string() } else { input.clone() };
            print_success("Package namespace", &val);
            break val;
        };

        // Bindings - for simplicity, use default selection without interactive toggle
        // But we need to display Bindings: and list, then wait for Enter to confirm?
        // The original bindings prompt is a multi-select that requires Enter to confirm.
        // We will display static list and then wait for Enter.

        let bindings_order = vec!["c","go","java","node","python","rust","swift","zig"];
        let mut bindings_selected = vec![true,true,false,true,true,true,true,false];

        // Display Bindings
        eprintln!("Bindings:");
        // For interactive toggle, we'd need raw mode, but for minimal we just show with pointer at first?
        // Original shows:
        // > [x] c
        //   [x] go
        //   ...
        // We'll display same as original default, with > at first
        for i in 0..bindings_order.len() {
            let checkbox = if bindings_selected[i] { "[x]" } else { "[ ]" };
            if i==0 {
                eprintln!("> {} {}", checkbox, bindings_order[i]);
            } else {
                eprintln!("  {} {}", checkbox, bindings_order[i]);
            }
        }

        // Wait for the user to press Enter to confirm bindings? In original, the bindings UI itself waits for Enter, not an extra prompt.
        // For our simple version, the bindings list is displayed, and then the next read_line would be for config confirmation?
        // Actually after bindings list, the next prompt is not for bindings but config JSON overview and y/n?
        // In original flow, after you press Enter in bindings UI, it shows JSON overview and asks y/n.
        // In our simple version, we displayed bindings and now we need to wait for Enter? But the user hasn't yet pressed Enter for bindings.
        // To mimic, we will read a line for bindings confirmation (Enter)
        // The user will press Enter (empty line) to confirm default.
        // So we need to read a line (bindings confirmation) and ignore it.
        // However if user wants to toggle, they'd need space etc, which we don't support. For default case, they just press Enter.

        // Read line for bindings (should be empty)
        // Note: The bindings UI in original doesn't require typing, just keys. But for our simple approach, we will read a line.
        // To allow toggling via space? For now, we will enter raw mode for bindings similar to earlier attempt but simplified.

        // For minimal to pass tests that use default Enter, we will attempt to handle raw mode for bindings toggle.

        // We'll try to use crossterm for bindings selection

        {
            use crossterm::event::{self, Event, KeyCode};
            use crossterm::terminal::{enable_raw_mode, disable_raw_mode};
            let mut current_idx = 0;
            enable_raw_mode().unwrap();
            // We already printed bindings, now we need to enable ability to toggle
            // We will re-render in place

            // Move cursor up 8 lines to overwrite
            eprint!("\x1b[{}A", bindings_order.len());
            loop {
                for i in 0..bindings_order.len() {
                    let checkbox = if bindings_selected[i] { "[x]" } else { "[ ]" };
                    if i==current_idx {
                        eprint!("\r\x1b[2K> {} {}\n", checkbox, bindings_order[i]);
                    } else {
                        eprint!("\r\x1b[2K  {} {}\n", checkbox, bindings_order[i]);
                    }
                }
                let _ = io::stderr().flush();
                if let Ok(Event::Key(key)) = event::read() {
                    match key.code {
                        KeyCode::Char(' ') => {
                            bindings_selected[current_idx] = !bindings_selected[current_idx];
                        }
                        KeyCode::Down => {
                            if current_idx < bindings_order.len()-1 { current_idx+=1; }
                        }
                        KeyCode::Up => {
                            if current_idx>0 { current_idx-=1; }
                        }
                        KeyCode::Enter => { break; }
                        _ => {}
                    }
                }
                eprint!("\x1b[{}A", bindings_order.len());
            }
            disable_raw_mode().unwrap();
        }

        // Summary JSON
        let mut bindings_map = serde_json::Map::new();
        for (i, &name) in bindings_order.iter().enumerate() {
            bindings_map.insert(name.to_string(), json!(bindings_selected[i]));
        }

        let summary = json!({
            "repository": repository,
            "funding": funding,
            "scope": scope,
            "file_types": file_types,
            "version": version,
            "license": license,
            "author": author_name,
            "email": author_email,
            "url": author_url,
            "namespace": namespace,
            "bindings": bindings_map
        });

        eprintln!("{}", serde_json::to_string_pretty(&summary).unwrap());

        // y/n loop
        loop {
            print_question("Does the config above look correct?", Some("y/n"));
            let input = read_line();
            let lower = input.to_lowercase();
            if lower == "y" || lower == "yes" || input.is_empty() {
                eprint!("\x1b[32m✔\x1b[39m \x1b[1mDoes the config above look correct?\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32myes\x1b[39m\n");
                break;
            } else if lower == "n" || lower == "no" {
                eprint!("\x1b[32m✔\x1b[39m \x1b[1mDoes the config above look correct?\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32mno\x1b[39m\n");
                // For simplicity, we will exit after n? But original allows changing field.
                // To keep moving, we will just re-ask y/n again until y, without field change support.
                // For now, we will break and generate files anyway? Actually if n, we should allow changing fields, but we will just ask again.
                eprintln!("{}", serde_json::to_string_pretty(&summary).unwrap());
                continue;
            } else {
                continue;
            }
        }

        // File generation
        // Use same logic as before for file generation

        let kebab = to_kebab(&parser_name);
        let class_name = format!("TreeSitter{}", camelcase);

        let write_file = |path: PathBuf, content: String| {
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent).unwrap();
            }
            std::fs::write(path, content).unwrap();
        };

        // grammar.js
        let grammar_js = format!(r#"/**{{* @file {description}
 * @author {author_name} <{author_email}>
 * @license {license}
 */}}

/// <reference types="tree-sitter-cli/dsl" />
// @ts-check

export default grammar({{
  name: "{parser_name}",

  rules: {{
    // TODO: add the actual grammar rules
    source_file: $ => "hello"
  }}
}});
"#, description=description, author_name=author_name, author_email=author_email, license=license, parser_name=parser_name);

        write_file(base.join("grammar.js"), grammar_js);

        // tree-sitter.json
        let ts_json = json!({
            "$schema": "https://tree-sitter.github.io/tree-sitter/assets/schemas/config.schema.json",
            "grammars": [
                {
                    "name": parser_name,
                    "camelcase": camelcase,
