            },
            "bindings": bindings_map
        });
        write_file(base.join("tree-sitter.json"), serde_json::to_string_pretty(&ts_json).unwrap() + "\n");

        // .editorconfig etc
        write_file(base.join(".editorconfig"), r#"root = true

