}

fn print_success(label: &str, value: &str) {
    eprint!("\x1b[32m✔\x1b[39m \x1b[1m{}\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32m{}\x1b[39m\n", label, value);
    let _ = io::stderr().flush();
}

fn print_error(msg: &str) {
    eprint!("\x1b[31m✘\x1b[39m \x1b[31m{}\x1b[39m\n", msg);
    let _ = io::stderr().flush();
}

fn read_line() -> String {
    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    s.trim_end_matches(&['\r','\n'][..]).to_string()
}

pub fn run_init(grammar_path: &str) {
    let base = PathBuf::from(grammar_path);
    std::fs::create_dir_all(&base).unwrap_or_else(|e| { eprintln!("\x1b[31mError:\x1b[0m {}", e); std::process::exit(1); });

    let parser_name = loop {
        print_question("Parser name", None);
        let input = read_line();
        if input.is_empty() { continue; }
        if !input.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_') {
            print_error("The name must be lowercase and contain only letters, digits, and underscores");
            continue;
        }
        print_success("Parser name", &input);
        break input;
    };

    let camel_default = to_camelcase(&parser_name);
    let camelcase = loop {
        print_question("CamelCase name", Some(&camel_default));
        let input = read_line();
        let val = if input.is_empty() { camel_default.clone() } else { input };
        print_success("CamelCase name", &val);
        break val;
    };

    let title_default = camelcase.clone();
    let title = loop {
        print_question("Title (human-readable name)", Some(&title_default));
        let input = read_line();
        let val = if input.is_empty() { title_default.clone() } else { input };
        print_success("Title (human-readable name)", &val);
        break val;
    };

    let description = loop {
        print_question("Description", None);
        let input = read_line();
        print_success("Description", &input);
        break input;
    };

    let repo_default = format!("https://github.com/tree-sitter/tree-sitter-{}", parser_name);
    let repository = loop {
        print_question("Repository URL", None);
        let input = read_line();
        let val = if input.is_empty() { repo_default.clone() } else { input };
        print_success("Repository URL", &val);
        break val;
    };

    let funding = loop {
        print_question("Funding URL", None);
        let input = read_line();
        print_success("Funding URL", &input);
        break input;
    };

    let scope_default = format!("source.{}", parser_name);
    let scope = loop {
        print_question("TextMate scope", Some(&scope_default));
        let input = read_line();
        let val = if input.is_empty() { scope_default.clone() } else { input };
        if !(val.starts_with("source.") || val.starts_with("text.")) {
            print_error("The scope must start with 'source.' or 'text.'");
            continue;
        }
        print_success("TextMate scope", &val);
        break val;
    };

    let filetypes_default = parser_name.clone();
    let file_types_input = loop {
        print_question("File types (space-separated)", Some(&filetypes_default));
        let input = read_line();
        let val = if input.is_empty() { filetypes_default.clone() } else { input };
        print_success("File types (space-separated)", &val);
        break val;
    };
    let file_types: Vec<String> = file_types_input.split_whitespace().map(|s| s.to_string()).collect();

    let version_default = "0.1.0";
    let version = loop {
        print_question("Version", Some(version_default));
        let input = read_line();
        let val = if input.is_empty() { version_default.to_string() } else { input };
        match semver::Version::parse(&val) {
            Ok(_) => { print_success("Version", &val); break val; }
            Err(e) => { print_error(&e.to_string()); continue; }
        }
    };

    let license_default = "MIT";
    let license = loop {
        print_question("License", Some(license_default));
        let input = read_line();
        let val = if input.is_empty() { license_default.to_string() } else { input };
        print_success("License", &val);
        break val;
    };

    let author_name = loop {
        print_question("Author name", None);
        let input = read_line();
        print_success("Author name", &input);
        break input;
    };

    let author_email = loop {
        print_question("Author email", None);
        let input = read_line();
        print_success("Author email", &input);
        break input;
    };

    let author_url = loop {
        print_question("Author URL", None);
        let input = read_line();
        print_success("Author URL", &input);
        break input;
    };

    let namespace_default = "io.github.tree-sitter";
    let namespace = loop {
        print_question("Package namespace", Some(namespace_default));
        let input = read_line();
        let val = if input.is_empty() { namespace_default.to_string() } else { input };
        print_success("Package namespace", &val);
        break val;
    };

    // Bindings selection - interactive with crossterm
    let bindings_order = vec!["c","go","java","node","python","rust","swift","zig"];
    let mut bindings_selected = vec![true,true,false,true,true,true,true,false];
    let mut current_idx = 0;

    eprintln!("Bindings:");

    enable_raw_mode().unwrap();
    // initial render will be done in loop
    eprint!("\x1b[{}A", 0); // no move
    loop {
        for i in 0..bindings_order.len() {
            let checkbox = if bindings_selected[i] { "[x]" } else { "[ ]" };
            if i==current_idx {
                eprint!("\r\x1b[2K> {} {}\n", checkbox, bindings_order[i]);
            } else {
                eprint!("\r\x1b[2K  {} {}\n", checkbox, bindings_order[i]);
            }
        }
        let _ = io::stderr().flush();
        if let Ok(Event::Key(key)) = event::read() {
            match key.code {
                KeyCode::Char(' ') => { bindings_selected[current_idx] = !bindings_selected[current_idx]; }
                KeyCode::Down => { if current_idx < bindings_order.len()-1 { current_idx+=1; } }
                KeyCode::Up => { if current_idx>0 { current_idx-=1; } }
                KeyCode::Enter => { break; }
                _ => {}
            }
        }
        eprint!("\x1b[{}A", bindings_order.len());
    }
    disable_raw_mode().unwrap();

    // Summary JSON
    let mut bindings_map = serde_json::Map::new();
    for (i, &name) in bindings_order.iter().enumerate() {
        bindings_map.insert(name.to_string(), json!(bindings_selected[i]));
    }

    let summary = json!({
        "repository": repository,
        "funding": funding,
        "scope": scope,
        "file_types": file_types,
        "version": version,
        "license": license,
        "author": author_name,
        "email": author_email,
        "url": author_url,
        "namespace": namespace,
        "bindings": bindings_map
    });

    eprintln!("{}", serde_json::to_string_pretty(&summary).unwrap());

    loop {
        print_question("Does the config above look correct?", Some("y/n"));
        let input = read_line();
        let lower = input.to_lowercase();
        if lower=="y" || lower=="yes" || input.is_empty() {
            eprint!("\x1b[32m✔\x1b[39m \x1b[1mDoes the config above look correct?\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32myes\x1b[39m\n");
            break;
        } else if lower=="n" || lower=="no" {
            eprint!("\x1b[32m✔\x1b[39m \x1b[1mDoes the config above look correct?\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32mno\x1b[39m\n");
            eprintln!("{}", serde_json::to_string_pretty(&summary).unwrap());
            continue;
        }
    }

    // Generate files - minimal for now, but we need to generate all expected

    let kebab = to_kebab(&parser_name);
    let class_name = format!("TreeSitter{}", camelcase);
    let upper = to_upper(&parser_name);

    let write_file = |path: PathBuf, content: String| {
        if let Some(parent) = path.parent() { std::fs::create_dir_all(parent).unwrap(); }
        std::fs::write(path, content).unwrap();
    };

    // .editorconfig, .gitattributes, .gitignore
    write_file(base.join(".editorconfig"), include_str!("templates/editorconfig.txt").to_string());
    write_file(base.join(".gitattributes"), include_str!("templates/gitattributes.txt").to_string());
    write_file(base.join(".gitignore"), include_str!("templates/gitignore.txt").to_string());

    // grammar.js
    let grammar_js = format!("/**\n * @file {description}\n * @author {author_name} <{author_email}>\n * @license {license}\n */\n\n/// <reference types=\"tree-sitter-cli/dsl\" />\n// @ts-check\n\nexport default grammar({{\n  name: \"{parser_name}\",\n\n  rules: {{\n    // TODO: add the actual grammar rules\n    source_file: $ => \"hello\"\n  }}\n}});\n", description=description, author_name=author_name, author_email=author_email, license=license, parser_name=parser_name);
    write_file(base.join("grammar.js"), grammar_js);

    // tree-sitter.json
    let ts_json = json!({
        "$schema": "https://tree-sitter.github.io/tree-sitter/assets/schemas/config.schema.json",
        "grammars": [{
            "name": parser_name,
            "camelcase": camelcase,
            "title": title,
            "scope": scope,
            "file-types": file_types,
            "injection-regex": format!("^{}$", parser_name),
            "class-name": class_name
        }],
        "metadata": {
            "version": version,
            "license": license,
            "description": description,
            "authors": [{
                "name": author_name,
                "email": author_email,
                "url": author_url
            }],
            "links": {
                "repository": repository,
                "funding": funding
            }
        },
        "bindings": bindings_map
    });
    write_file(base.join("tree-sitter.json"), serde_json::to_string_pretty(&ts_json).unwrap() + "\n");

    // package.json always
    let pkg = json!({
        "name": format!("tree-sitter-{}", kebab),
        "version": version,
        "description": description,
        "type": "module",
        "repository": {
            "type": "git",
            "url": format!("git+{}.git", repository)
        },
        "funding": funding,
        "license": license,
        "author": {
            "name": author_name,
            "email": author_email,
            "url": author_url
        },
        "main": "bindings/node",
        "types": "bindings/node",
        "keywords": ["incremental", "parsing", "tree-sitter", parser_name],
        "files": ["grammar.js", "tree-sitter.json", "binding.gyp", "prebuilds/**", "bindings/node/*", "queries/*", "src/**", "*.wasm"],
        "dependencies": {
            "node-addon-api": "^8.5.0",
            "node-gyp-build": "^4.8.4"
        },
        "devDependencies": {
            "prebuildify": "^6.0.1",
            "tree-sitter": "^0.25.0",
            "tree-sitter-cli": "^0.27.0"
        },
        "peerDependencies": {
            "tree-sitter": "^0.25.0"
        },
        "peerDependenciesMeta": {
            "tree-sitter": {
                "optional": true
            }
        },
        "scripts": {
            "install": "node-gyp-build",
            "prestart": "tree-sitter build --wasm",
            "start": "tree-sitter playground",
            "test": "node --test bindings/node/*_test.js"
        }
    });
    write_file(base.join("package.json"), serde_json::to_string_pretty(&pkg).unwrap() + "\n");

    // c binding files if enabled
    if bindings_selected[0] {
        let cmake = format!(r#"cmake_minimum_required(VERSION 3.13)

