        let lib_rs = format!("//! This crate provides {title} language support for the [tree-sitter] parsing library.\n//!\n//! Typically, you will use the [`LANGUAGE`] constant to add this language to a\n//! tree-sitter [`Parser`], and then use the parser to parse some code:\n//!\n//! ```\n//! let code = r#\"\n//! \"#;\n//! let mut parser = tree_sitter::Parser::new();\n//! let language = tree_sitter_{parser_name}::LANGUAGE;\n//! parser\n//!     .set_language(&language.into())\n//!     .expect(\"Error loading {title} parser\");\n//! let tree = parser.parse(code, None).unwrap();\n//! assert!(!tree.root_node().has_error());\n//! ```\n//!\n//! [`Parser`]: https://docs.rs/tree-sitter/0.27.0/tree_sitter/struct.Parser.html\n//! [tree-sitter]: https://tree-sitter.github.io/\n\nuse tree_sitter_language::LanguageFn;\n\nunsafe extern \"C\" {{\n    fn tree_sitter_{parser_name}() -> *const ();\n}}\n\n/// The tree-sitter [`LanguageFn`] for this grammar.\npub const LANGUAGE: LanguageFn = unsafe {{ LanguageFn::from_raw(tree_sitter_{parser_name}) }};\n\n/// The content of the [`node-types.json`] file for this grammar.\n///\n/// [`node-types.json`]: https://tree-sitter.github.io/tree-sitter/using-parsers/6-static-node-types\npub const NODE_TYPES: &str = include_str!(\"../../src/node-types.json\");\n\n#[cfg(with_highlights_query)]\n/// The syntax highlighting query for this grammar.\npub const HIGHLIGHTS_QUERY: &str = include_str!(\"../../queries/highlights.scm\");\n\n#[cfg(with_injections_query)]\n/// The language injection query for this grammar.\npub const INJECTIONS_QUERY: &str = include_str!(\"../../queries/injections.scm\");\n\n#[cfg(with_locals_query)]\n/// The local variable query for this grammar.\npub const LOCALS_QUERY: &str = include_str!(\"../../queries/locals.scm\");\n\n#[cfg(with_tags_query)]\n/// The symbol tagging query for this grammar.\npub const TAGS_QUERY: &str = include_str!(\"../../queries/tags.scm\");\n\n#[cfg(test)]\nmod tests {{\n    #[test]\n    fn test_can