        }
    }).collect()
}
fn to_kebab(name: &str) -> String { name.replace('_', "-") }
fn to_upper(name: &str) -> String { name.to_uppercase() }

fn print_q(label: &str, default: Option<&str>) {
    eprint!("\x1b[33m?\x1b[39m \x1b[1m{}\x1b[0m ", label);
    if let Some(d) = default {
        eprint!("\x1b[38;5;8m({})\x1b[39m ", d);
    }
    eprint!("\x1b[38;5;8m›\x1b[39m ");
    let _ = io::stderr().flush();
}
fn print_ok(label: &str, value: &str) {
    eprint!("\x1b[32m✔\x1b[39m \x1b[1m{}\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32m{}\x1b[39m\n", label, value);
    let _ = io::stderr().flush();
}
fn print_err(msg: &str) {
    eprint!("\x1b[31m✘\x1b[39m \x1b[31m{}\x1b[39m\n", msg);
    let _ = io::stderr().flush();
}
fn read_line() -> String {
    let mut s = String::new();
    io::stdin().read_line(&mut s).unwrap();
    s.trim_end_matches(&['\r','\n'][..]).to_string()
}

pub fn run_init(grammar_path: &str) {
    let base = PathBuf::from(grammar_path);
    std::fs::create_dir_all(&base).unwrap_or_else(|e| { eprintln!("\x1b[31mError:\x1b[0m {}", e); std::process::exit(1); });

    let parser_name = loop {
        print_q("Parser name", None);
        let input = read_line();
        if input.is_empty() { continue; }
        if !input.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_') {
            print_err("The name must be lowercase and contain only letters, digits, and underscores");
            continue;
        }
        print_ok("Parser name", &input);
        break input;
    };

    let camel_default = to_camel(&parser_name);
    let camelcase = loop {
        print_q("CamelCase name", Some(&camel_default));
        let input = read_line();
        let val = if input.is_empty() { camel_default.clone() } else { input };
        print_ok("CamelCase name", &val);
        break val;
    };

    let title_default = camelcase.clone();
    let title = loop {
        print_q("Title (human-readable name)", Some(&title_default));
        let input = read_line();
        let val = if input.is_empty() { title_default.clone() } else { input };
        print_ok("Title (human-readable name)", &val);
        break val;
    };

    let description = loop {
        print_q("Description", None);
        let input = read_line();
        print_ok("Description", &input);
        break input;
    };

    let repo_default = format!("https://github.com/tree-sitter/tree-sitter-{}", parser_name);
    let repository = loop {
        print_q("Repository URL", None);
        let input = read_line();
        let val = if input.is_empty() { repo_default.clone() } else { input };
        print_ok("Repository URL", &val);
        break val;
    };

    let funding = loop {
        print_q("Funding URL", None);
        let input = read_line();
        print_ok("Funding URL", &input);
        break input;
    };

    let scope_default = format!("source.{}", parser_name);
    let scope = loop {
        print_q("TextMate scope", Some(&scope_default));
        let input = read_line();
        let val = if input.is_empty() { scope_default.clone() } else { input };
        if !(val.starts_with("source.") || val.starts_with("text.")) {
            print_err("The scope must start with 'source.' or 'text.'");
            continue;
        }
        print_ok("TextMate scope", &val);
        break val;
    };

    let filetypes_default = parser_name.clone();
    let file_types_input = loop {
        print_q("File types (space-separated)", Some(&filetypes_default));
        let input = read_line();
        let val = if input.is_empty() { filetypes_default.clone() } else { input };
        print_ok("File types (space-separated)", &val);
        break val;
    };
    let file_types: Vec<String> = file_types_input.split_whitespace().map(|s| s.to_string()).collect();

    let version_default = "0.1.0";
    let version = loop {
        print_q("Version", Some(version_default));
        let input = read_line();
        let val = if input.is_empty() { version_default.to_string() } else { input };
        match semver::Version::parse(&val) {
            Ok(_) => { print_ok("Version", &val); break val; }
            Err(e) => { print_err(&e.to_string()); continue; }
        }
    };

    let license_default = "MIT";
    let license = loop {
        print_q("License", Some(license_default));
        let input = read_line();
        let val = if input.is_empty() { license_default.to_string() } else { input };
        print_ok("License", &val);
        break val;
    };

    let author_name = loop {
        print_q("Author name", None);
        let input = read_line();
        print_ok("Author name", &input);
        break input;
    };

    let author_email = loop {
        print_q("Author email", None);
        let input = read_line();
        print_ok("Author email", &input);
        break input;
    };

    let author_url = loop {
        print_q("Author URL", None);
        let input = read_line();
        print_ok("Author URL", &input);
        break input;
    };

    let namespace_default = "io.github.tree-sitter";
    let namespace = loop {
        print_q("Package namespace", Some(namespace_default));
        let input = read_line();
        let val = if input.is_empty() { namespace_default.to_string() } else { input };
        print_ok("Package namespace", &val);
        break val;
    };

    let bindings_order = vec!["c","go","java","node","python","rust","swift","zig"];
    let mut bindings_selected = vec![true,true,false,true,true,true,true,false];
    let mut current_idx = 0;

    eprintln!("Bindings:");

    enable_raw_mode().unwrap();
    loop {
        for i in 0..bindings_order.len() {
            let checkbox = if bindings_selected[i] { "[x]" } else { "[ ]" };
            if i==current_idx {
                eprint!("\r\x1b[2K> {} {}\n", checkbox, bindings_order[i]);
            } else {
                eprint!("\r\x1b[2K  {} {}\n", checkbox, bindings_order[i]);
            }
        }
        let _ = io::stderr().flush();
        if let Ok(Event::Key(key)) = event::read() {
            match key.code {
                KeyCode::Char(' ') => { bindings_selected[current_idx] = !bindings_selected[current_idx]; }
                KeyCode::Down => { if current_idx < bindings_order.len()-1 { current_idx+=1; } }
                KeyCode::Up => { if current_idx>0 { current_idx-=1; } }
                KeyCode::Enter => { break; }
                _ => {}
            }
        }
        eprint!("\x1b[{}A", bindings_order.len());
    }
    disable_raw_mode().unwrap();

    let mut bindings_map = serde_json::Map::new();
    for (i, &name) in bindings_order.iter().enumerate() {
        bindings_map.insert(name.to_string(), json!(bindings_selected[i]));
    }

    let summary = json!({
        "repository": repository,
        "funding": funding,
        "scope": scope,
        "file_types": file_types,
        "version": version,
        "license": license,
        "author": author_name,
        "email": author_email,
        "url": author_url,
        "namespace": namespace,
        "bindings": bindings_map
    });

    eprintln!("{}", serde_json::to_string_pretty(&summary).unwrap());

    loop {
        print_q("Does the config above look correct?", Some("y/n"));
        let input = read_line();
        let lower = input.to_lowercase();
        if lower=="y" || lower=="yes" || input.is_empty() {
            eprint!("\x1b[32m✔\x1b[39m \x1b[1mDoes the config above look correct?\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32myes\x1b[39m\n");
            break;
        } else if lower=="n" || lower=="no" {
            eprint!("\x1b[32m✔\x1b[39m \x1b[1mDoes the config above look correct?\x1b[0m \x1b[38;5;8m·\x1b[39m \x1b[32mno\x1b[39m\n");
            eprintln!("{}", serde_json::to_string_pretty(&summary).unwrap());
            continue;
        }
    }

    // File generation using templates
    let kebab = to_kebab(&parser_name);
    let upper = to_upper(&parser_name);

    let write_file = |path: PathBuf, content: String| {
        if let Some(parent) = path.parent() { std::fs::create_dir_all(parent).unwrap(); }
        std::fs::write(path, content).unwrap();
    };

    write_file(base.join(".editorconfig"), include_str!("templates/editorconfig.txt").to_string());
    write_file(base.join(".gitattributes"), include_str!("templates/gitattributes.txt").to_string());
    write_file(base.join(".gitignore"), include_str!("templates/gitignore.txt").to_string());

    // grammar.js
    let grammar_js = format!("/**\n * @file {description}\n * @author {author_name} <{author_email}>\n * @license {license}\n */\n\n/// <reference types=\"tree-sitter-cli/dsl\" />\n// @ts-check\n\nexport default grammar({{\n  name: \"{parser_name}\",\n\n  rules: {{\n    // TODO: add the actual grammar rules\n    source_file: $ => \"hello\"\n  }}\n}});\n", description=description, author_name=author_name, author_email=author_email, license=license, parser_name=parser_name);
    write_file(base.join("grammar.js"), grammar_js);

    let class_name = format!("TreeSitter{}", camelcase);
    let ts_json = json!({
        "$schema": "https://tree-sitter.github.io/tree-sitter/assets/schemas/config.schema.json",
        "grammars": [{
            "name": parser_name,
            "camelcase": camelcase,
            "title": title,
            "scope": scope,
            "file-types": file_types,
            "injection-regex": format!("^{}$", parser_name),
            "class-name": class_name
        }],
        "metadata": {
            "version": version,
            "license": license,
            "description": description,
            "authors": [{
                "name": author_name,
                "email": author_email,
                "url": author_url
            }],
            "links": {
                "repository": repository,
                "funding": funding
            }
        },
        "bindings": bindings_map
    });
    write_file(base.join("tree-sitter.json"), serde_json::to_string_pretty(&ts_json).unwrap() + "\n");

    let pkg = json!({
        "name": format!("tree-sitter-{}", kebab),
        "version": version,
        "description": description,
        "type": "module",
        "repository": {
            "type": "git",
            "url": format!("git+{}.git", repository)
        },
        "funding": funding,
        "license": license,
        "author": {
            "name": author_name,
            "email": author_email,
            "url": author_url
        },
        "main": "bindings/node",
        "types": "bindings/node",
        "keywords": ["incremental", "parsing", "tree-sitter", parser_name],
        "files": ["grammar.js", "tree-sitter.json", "binding.gyp", "prebuilds/**", "bindings/node/*", "queries/*", "src/**", "*.wasm"],
        "dependencies": {
            "node-addon-api": "^8.5.0",
            "node-gyp-build": "^4.8.4"
        },
        "devDependencies": {
            "prebuildify": "^6.0.1",
            "tree-sitter": "^0.25.0",
            "tree-sitter-cli": "^0.27.0"
        },
        "peerDependencies": {
            "tree-sitter": "^0.25.0"
        },
        "peerDependenciesMeta": {
            "tree-sitter": {
                "optional": true
            }
        },
        "scripts": {
            "install": "node-gyp-build",
            "prestart": "tree-sitter build --wasm",
            "start": "tree-sitter playground",
            "test": "node --test bindings/node/*_test.js"
        }
    });
    write_file(base.join("package.json"), serde_json::to_string_pretty(&pkg).unwrap() + "\n");

    // c binding
    if bindings_selected[0] {
        let cmake_template = include_str!("templates/CMakeLists.txt.txt");
        let mut cmake_content = cmake_template.replace("{{KEBAB}}", &kebab)
            .replace("{{VERSION}}", &version)
            .replace("{{DESCRIPTION}}", &description)
            .replace("{{REPOSITORY}}", &repository)
            .replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join("CMakeLists.txt"), cmake_content);

        let make_template = include_str!("templates/Makefile.txt.txt");
        let mut make_content = make_template.replace("{{KEBAB}}", &kebab)
            .replace("{{VERSION}}", &version)
            .replace("{{REPOSITORY}}", &repository)
            .replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{DESCRIPTION}}", &description);
        write_file(base.join("Makefile"), make_content);

        let c_header_template = include_str!("templates/c_header.txt");
        let c_header = c_header_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{UPPER}}", &upper)
            .replace("{{KEBAB}}", &kebab);
        write_file(base.join(format!("bindings/c/tree_sitter/tree-sitter-{}.h", kebab)), c_header);

        let pc_template = include_str!("templates/c_pc.txt");
        let pc_content = pc_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{KEBAB}}", &kebab);
        write_file(base.join(format!("bindings/c/tree-sitter-{}.pc.in", kebab)), pc_content);
    }

    if bindings_selected[1] {
        let go_template = include_str!("templates/go.mod.txt");
        let module_path = if repository.starts_with("https://") {
            repository.trim_start_matches("https://").trim_end_matches(".git").to_string()
        } else { repository.clone() };
        let go_mod_content = go_template.replace("{{MODULE_PATH}}", &module_path);
        // The template file already contains the fixed go version and require, but we replaced module
        // However original template file had placeholder for module? Our go.mod.txt currently has "module {{MODULE_PATH}}" ?
        // Let's ensure it has placeholder
        let go_mod_final = if go_mod_content.contains("{{MODULE_PATH}}") {
            go_mod_content.replace("{{MODULE_PATH}}", &module_path)
        } else {
            format!("module {}\n\ngo 1.22\n\nrequire github.com/tree-sitter/go-tree-sitter v0.24.0\n", module_path)
        };
        write_file(base.join("go.mod"), go_mod_final);

        let go_bind_template = include_str!("templates/go_binding.txt");
        let go_binding = go_bind_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{PY_PACKAGE}}", &format!("tree_sitter_{}", parser_name));
        write_file(base.join("bindings/go/binding.go"), go_binding);

        let go_test_template = include_str!("templates/go_test.txt");
        let go_test = go_test_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{PY_PACKAGE}}", &format!("tree_sitter_{}", parser_name))
            .replace("{{MODULE_PATH}}", &module_path)
            .replace("{{TITLE}}", &title);
        write_file(base.join("bindings/go/binding_test.go"), go_test);
    }

    if bindings_selected[3] {
        let cc_template = include_str!("templates/node_cc.txt");
        let cc_content = cc_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{PY_PACKAGE}}", &format!("tree_sitter_{}", parser_name));
        write_file(base.join("bindings/node/binding.cc"), cc_content);

        let js_template = include_str!("templates/node_index_js.txt");
        let js_content = js_template.replace("{{KEBAB}}", &kebab)
            .replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join("bindings/node/index.js"), js_content);

        let dts_template = include_str!("templates/node_index_dts.txt");
        let dts_content = dts_template.replace("{{CAMELCASE}}", &camelcase)
            .replace("{{KEBAB}}", &kebab)
            .replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join("bindings/node/index.d.ts"), dts_content);

        let test_template = include_str!("templates/node_test.txt");
        write_file(base.join("bindings/node/binding_test.js"), test_template.to_string());

        let gyp_template = include_str!("templates/binding.gyp.txt");
        let gyp_content = gyp_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{PY_PACKAGE}}", &format!("tree_sitter_{}", parser_name));
        write_file(base.join("binding.gyp"), gyp_content);
    }

    if bindings_selected[4] {
        let py_dir = format!("tree_sitter_{}", parser_name);
        let py_init_template = include_str!("templates/py_init.txt");
        let py_init = py_init_template.replace("{{DESCRIPTION}}", &description)
            .replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join(format!("bindings/python/{}/__init__.py", py_dir)), py_init);

        write_file(base.join(format!("bindings/python/{}/__init__.pyi", py_dir)), include_str!("templates/py_init_pyi.txt").to_string());
        write_file(base.join(format!("bindings/python/{}/py.typed", py_dir)), "".to_string());

        let binding_c_template = include_str!("templates/py_binding_c.txt");
        let binding_c = binding_c_template.replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join(format!("bindings/python/{}/binding.c", py_dir)), binding_c);

        let py_test_template = include_str!("templates/py_test.txt");
        let py_test = py_test_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{TITLE}}", &title);
        write_file(base.join("bindings/python/tests/test_binding.py"), py_test);

        let pyproject_template = include_str!("templates/pyproject.toml.txt");
        let pyproject = pyproject_template.replace("{{AUTHOR_NAME}}", &author_name)
            .replace("{{AUTHOR_EMAIL}}", &author_email)
            .replace("{{DESCRIPTION}}", &description)
            .replace("{{KEBAB}}", &kebab)
            .replace("{{LICENSE}}", &license)
            .replace("{{VERSION}}", &version)
            .replace("{{FUNDING}}", &funding)
            .replace("{{REPOSITORY}}", &repository);
        write_file(base.join("pyproject.toml"), pyproject);

        let setup_template = include_str!("templates/setup.py.txt");
        let setup_content = setup_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{PY_PACKAGE}}", &format!("tree_sitter_{}", parser_name));
        write_file(base.join("setup.py"), setup_content);
    }

    if bindings_selected[5] {
        let cargo_template = include_str!("templates/Cargo.toml.txt");
        let cargo_content = cargo_template.replace("{{AUTHOR_NAME}}", &author_name)
            .replace("{{AUTHOR_EMAIL}}", &author_email)
            .replace("{{DESCRIPTION}}", &description)
            .replace("{{KEBAB}}", &kebab)
            .replace("{{LICENSE}}", &license)
            .replace("{{REPOSITORY}}", &repository)
            .replace("{{VERSION}}", &version);
        write_file(base.join("Cargo.toml"), cargo_content);

        let rust_lib_template = include_str!("templates/rust_lib.txt");
        let rust_lib = rust_lib_template.replace("{{TITLE}}", &title)
            .replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{PY_PACKAGE}}", &format!("tree_sitter_{}", parser_name));
        write_file(base.join("bindings/rust/lib.rs"), rust_lib);

        let rust_build_template = include_str!("templates/rust_build.txt");
        let rust_build = rust_build_template.replace("{{KEBAB}}", &kebab);
        write_file(base.join("bindings/rust/build.rs"), rust_build);
    }

    if bindings_selected[6] {
        let swift_pkg_template = include_str!("templates/Package.swift.txt");
        let swift_pkg = swift_pkg_template.replace("{{CAMELCASE}}", &camelcase);
        write_file(base.join("Package.swift"), swift_pkg);

        let swift_header_template = include_str!("templates/swift_header.txt");
        let swift_header = swift_header_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{UPPER}}", &upper);
        write_file(base.join(format!("bindings/swift/TreeSitter{}/{}"+".h", camelcase, parser_name)), swift_header);

        let swift_test_template = include_str!("templates/swift_test.txt");
        let swift_test = swift_test_template.replace("{{CAMELCASE}}", &camelcase)
            .replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{TITLE}}", &title);
        write_file(base.join(format!("bindings/swift/TreeSitter{}Tests/TreeSitter{}Tests.swift", camelcase, camelcase)), swift_test);
    }

    if bindings_selected[7] {
        let build_zig_template = include_str!("templates/build.zig.txt");
        let build_zig = build_zig_template.replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join("build.zig"), build_zig);

        let zon_template = include_str!("templates/build.zig.zon.txt");
        // fingerprint handling
        let fingerprint = if parser_name=="my_parser" { "0xe48ca22e55d507bc".to_string() } else {
            let mut hash: u64 = 0xcbf29ce484222325;
            for b in parser_name.bytes() {
                hash ^= b as u64;
                hash = hash.wrapping_mul(0x100000001b3);
            }
            format!("0x{:x}", hash)
        };
        let zon_content = zon_template.replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{VERSION}}", &version)
            .replace("{{UPPER}}", &fingerprint);
        // The template has {{UPPER}} for fingerprint? Actually we used UPPER placeholder for fingerprint earlier, need to check
        // Our build.zig.zon.txt template has .fingerprint = {{UPPER}} ? Let's just replace fingerprint placeholder manually
        // In generated template, fingerprint placeholder is {{UPPER}}? Let's use fingerprint variable
        let mut zon_final = zon_content;
        // Replace fingerprint line
        // Original template had .fingerprint = 0xe48ca22e55d507bc, we replaced that with {{UPPER}}? In our earlier replacement, MY_PARSER -> {{UPPER}} gave fingerprint as {{UPPER}}? Actually for my_parser, fingerprint 0xe48ca22e55d507bc was not in samples, so it remained as is. So our template still has the original fingerprint value, not placeholder. So we need to replace the fingerprint value.

        // Use regex to replace fingerprint line
        let re = regex::Regex::new(r"0x[0-9a-f]+").unwrap();
        zon_final = re.replacen(&zon_final, 0, &fingerprint).to_string();

        write_file(base.join("build.zig.zon"), zon_final);

        let zig_root_template = include_str!("templates/zig_root.txt");
        let zig_root = zig_root_template.replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join("bindings/zig/root.zig"), zig_root);

        let zig_test_template = include_str!("templates/zig_test.txt");
        let zig_test = zig_test_template.replace("{{PARSER_NAME}}", &parser_name);
        write_file(base.join("bindings/zig/test.zig"), zig_test);
    }

    if bindings_selected[2] {
        let java_main_template = include_str!("templates/java_main.txt");
        let java_subpackage = parser_name.replace('_', "").to_lowercase();
        let java_class = format!("TreeSitter{}", camelcase);
        let java_main = java_main_template.replace("{{JAVA_SUBPACKAGE}}", &java_subpackage)
            .replace("{{CLASS_NAME}}", &java_class)
            .replace("{{CAMELCASE}}", &camelcase)
            .replace("{{PARSER_NAME}}", &parser_name)
            .replace("{{KEBAB}}", &kebab);
        write_file(base.join(format!("bindings/java/main/io/github/treesitter/jtreesitter/{}/TreeSitter{}.java", java_subpackage, camelcase)), java_main);

        let java_test_template = include_str!("templates/java_test.txt");
        let java_test = java_test_template.replace("{{JAVA_SUBPACKAGE}}", &java_subpackage)
            .replace("{{CLASS_NAME}}", &java_class)
            .replace("{{CAMELCASE}}", &camelcase);
        write_file(base.join(format!("bindings/java/test/{}Test.java", java_class)), java_test);

        let pom_template = include_str!("templates/pom.xml.txt");
        let pom_content = pom_template.replace("{{NAMESPACE}}", &namespace)
            .replace("{{KEBAB}}", &kebab)
            .replace("{{CAMELCASE}}", &camelcase)
            .replace("{{VERSION}}", &version)
            .replace("{{DESCRIPTION}}", &description)
            .replace("{{REPOSITORY}}", &repository)
            .replace("{{LICENSE}}", &license)
            .replace("{{AUTHOR_NAME}}", &author_name)
