    let class_name = format!("TreeSitter{}", camelcase);
    let swift_test_class = format!("TreeSitter{}Tests", camelcase);
    s = s.replace("{{PARSER_NAME}}", parser_name);
    s = s.replace("{{CAMELCASE}}", camelcase);
    s = s.replace("{{TITLE}}", title);
    s = s.replace("{{DESCRIPTION}}", description);
    s = s.replace("{{REPOSITORY}}", repository);
    s = s.replace("{{FUNDING}}", funding);
    s = s.replace("{{SCOPE}}", scope);
    s = s.replace("{{VERSION}}", version);
    s = s.replace("{{LICENSE}}", license);
    s = s.replace("{{AUTHOR_NAME}}", author_name);
    s = s.replace("{{AUTHOR_EMAIL}}", author_email);
    s = s.replace("{{AUTHOR_URL}}", author_url);
    s = s.replace("{{NAMESPACE}}", namespace);
    s = s.replace("{{KEBAB}}", kebab);
    s = s.replace("{{UPPER}}", upper);
    s = s.replace("{{PY_PACKAGE}}", &py_package);
    s = s.replace("{{MODULE_PATH}}", &module_path);
    s = s.replace("{{JAVA_SUBPACKAGE}}", &java_subpackage);
    s = s.replace("{{CLASS_NAME}}", &class_name);
    s = s.replace("{{SWIFT_TEST_CLASS}}", &swift_test_class);
    s
}

fn print_q(label: &str, default: Option<&str>) {
    eprint!("\x1b[33m?\x1b[39m \x1b[1m{}\x1b[0m ", label);
    if let Some(d) = default {
        eprint!("\x1b[38;5;8m({})\x1b[39m ", d);
    }
    eprint!("\x1b[38;5;8m›\x1b[39m ");
    let _ = io::stderr().flush();
}
fn print_ok(label: &str, value: &str) {
