fn to_camel(name: &str) -> String {
    name.split('_').map(|part| {
        let mut chars = part.chars();
        match chars.next() {
            None => String::new(),
            Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        }
    }).collect()
}
fn to_kebab(name: &str) -> String { name.replace('_', "-") }
fn to_upper(name: &str) -> String { name.to_uppercase() }

fn replace_all(template: &str, parser_name: &str, camelcase: &str, title: &str, description: &str, repository: &str, funding: &str, scope: &str, version: &str, license: &str, author_name: &str, author_email: &str, author_url: &str, namespace: &str, kebab: &str, upper: &str) -> String {
