        print_q("Package namespace", Some(namespace_default));
        let input = read_line();
        let val = if input.is_empty() { namespace_default.to_string() } else { input };
        print_ok("Package namespace", &val);
        break val;
    };

    let bindings_order = vec!["c","go","java","node","python","rust","swift","zig"];
    let mut bindings_selected = vec![true,true,false,true,true,true,true,false];
    let mut current_idx = 0;

    eprintln!("Bindings:");

    enable_raw_mode().unwrap();
    loop {
        for i in 0..bindings_order.len() {
            let checkbox = if bindings_selected[i] { "[x]" } else { "[ ]" };
            if i==current_idx {
                eprint!("\r\x1b[2K> {} {}\n", checkbox, bindings_order[i]);
            } else {
                eprint!("\r\x1b[2K  {} {}\n", checkbox, bindings_order[i]);
            }
        }
        let _ = io::stderr().flush();
        if let Ok(Event::Key(key)) = event::read() {
            match key.code {
                KeyCode::Char(' ') => { bindings_selected[current_idx] = !bindings_selected[current_idx]; }
                KeyCode::Down => { if current_idx < bindings_order.len()-1 { current_idx+=1; } }
                KeyCode::Up => { if current_idx>0 { current_idx-=1; } }
                KeyCode::Enter => { break; }
                _ => {}
            }
        }
        eprint!("\x1b[{}A", bindings_order.len());
    }
    disable_raw_mode().unwrap();

    let mut bindings_map = serde_json::Map::new();
    for (i, &name) in bindings_order.iter().enumerate() {
